// Developer tests for slice 43's pure asset functions (D7 §6.1 to §6.3;
// SEAM.md §§505 to 507): the header reads (format by magic bytes, a raster's
// size and alpha channel from its header alone, an active SVG), and the
// placeholders merged into an existing manifest when a target is added.
// Every file here is generated bytes with a valid header; nothing is decoded.

import assert from 'node:assert/strict';
import { dirname, join } from 'node:path';
import { test } from 'node:test';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { crc32, deflateSync } from 'node:zlib';

const here = dirname(fileURLToPath(import.meta.url));
const dist = join(here, '..', '..', 'dist');
const { headerReasons, rasterHeader, mergePlaceholders, placeholderManifest } = await import(pathToFileURL(join(dist, 'design', 'assets.js')).href);

const SIG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const chunk = (type, data) => {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const typed = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(typed) >>> 0);
  return Buffer.concat([len, typed, crc]);
};
const ihdr = (w, h, colorType) => {
  const b = Buffer.alloc(13);
  b.writeUInt32BE(w, 0);
  b.writeUInt32BE(h, 4);
  b[8] = 8;
  b[9] = colorType;
  return b;
};
const png = (w, h, colorType, extra = []) => Buffer.concat([SIG, chunk('IHDR', ihdr(w, h, colorType)), ...extra, chunk('IDAT', deflateSync(Buffer.alloc(1))), chunk('IEND', Buffer.alloc(0))]);
const codes = (r) => r.map((x) => x.code);

test('a PNG: its size and alpha channel from IHDR and a tRNS before IDAT; image data never read', () => {
  assert.deepEqual(rasterHeader(png(32, 16, 2), 'png').sizes, [{ w: 32, h: 16, alpha: false }]);
  assert.deepEqual(rasterHeader(png(32, 16, 6), 'png').sizes, [{ w: 32, h: 16, alpha: true }]);
  assert.deepEqual(rasterHeader(png(32, 16, 2, [chunk('tRNS', Buffer.alloc(6))]), 'png').sizes, [{ w: 32, h: 16, alpha: true }]);
  // IDAT that is not zlib at all: the header is all that is read.
  const bogus = Buffer.concat([SIG, chunk('IHDR', ihdr(20000, 20000, 2)), chunk('IDAT', Buffer.from('not zlib')), chunk('IEND', Buffer.alloc(0))]);
  assert.deepEqual(headerReasons(bogus, { format: 'png', size: { w: 20000, h: 20000 }, transparency: 'forbidden' }, { slot: 's' }), []);
});

test('each header reason, and a cut-off header refused naming the file', () => {
  const file = { slot: 'favicon', variant: 'default', file: 'assets/x.png' };
  assert.deepEqual(codes(headerReasons(png(32, 32, 2), { format: 'svg', transparency: 'any' }, file)), ['DESIGN_ASSET_FORMAT_MISMATCH']);
  assert.deepEqual(codes(headerReasons(png(32, 32, 2), { format: 'png', size: { w: 48, h: 48 }, transparency: 'any' }, file)), ['DESIGN_ASSET_SIZE_MISMATCH']);
  assert.deepEqual(codes(headerReasons(png(48, 48, 6), { format: 'png', size: { w: 48, h: 48 }, transparency: 'forbidden' }, file)), ['DESIGN_ASSET_TRANSPARENCY_MISMATCH']);
  assert.deepEqual(codes(headerReasons(png(48, 48, 2), { format: 'png', size: { w: 48, h: 48 }, transparency: 'required' }, file)), ['DESIGN_ASSET_TRANSPARENCY_MISMATCH']);
  const cut = headerReasons(Buffer.concat([SIG, Buffer.from([0, 0, 0, 13])]), { format: 'png', size: { w: 48, h: 48 }, transparency: 'any' }, file);
  assert.equal(cut.length, 1);
  assert.equal(cut[0].subjects.file, 'assets/x.png');
  assert.deepEqual(codes(headerReasons(Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"><script>x()</script></svg>'), { format: 'svg', transparency: 'any' }, file)), ['DESIGN_ASSET_SVG_ACTIVE']);
  assert.deepEqual(codes(headerReasons(Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"><image href="https://e.org/a.png"/></svg>'), { format: 'svg', transparency: 'any' }, file)), ['DESIGN_ASSET_SVG_ACTIVE']);
  assert.deepEqual(headerReasons(Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"><use href="#a"/></svg>'), { format: 'svg', transparency: 'any' }, file), []);
});

test('a WebP VP8X header gives its canvas and alpha flag', () => {
  const vp8x = Buffer.alloc(10);
  vp8x[0] = 0x10;
  vp8x.writeUIntLE(63, 4, 3);
  vp8x.writeUIntLE(31, 7, 3);
  const body = Buffer.concat([Buffer.from('WEBPVP8X', 'ascii'), Buffer.from([10, 0, 0, 0]), vp8x]);
  const head = Buffer.concat([Buffer.from('RIFF', 'ascii'), Buffer.alloc(4)]);
  head.writeUInt32LE(body.length, 4);
  assert.deepEqual(rasterHeader(Buffer.concat([head, body]), 'webp').sizes, [{ w: 64, h: 32, alpha: true }]);
});

test('a target added later: its slots and variants placed, existing slots keep their files and versions', () => {
  const before = placeholderManifest('pantry', ['web', 'android']);
  const logo = before.manifest.slots.find((s) => s.kind === 'logo');
  logo.variants[0] = { ...logo.variants[0], file: 'assets/m/logo.svg', digest: 'a'.repeat(64) };
  logo.slot_version = 2;
  logo.status = 'proposed';
  const merged = mergePlaceholders(before.manifest, placeholderManifest('pantry', ['web', 'android', 'ios']));
  assert.equal(merged.changed, true);
  assert.equal(merged.manifest.version, before.manifest.version + 1);
  const by = Object.fromEntries(merged.manifest.slots.map((s) => [s.key, s]));
  assert.deepEqual(by.splash.platforms, ['ios']);
  assert.ok(merged.files[by.splash.variants[0].file]);
  assert.deepEqual([by.logo.slot_version, by.logo.variants[0].file, by.logo.platforms.includes('ios')], [2, 'assets/m/logo.svg', true]);
  assert.deepEqual([by.app_icon.slot_version, by.app_icon.platforms.includes('ios')], [1, true]);
  assert.equal(mergePlaceholders(merged.manifest, placeholderManifest('pantry', ['web', 'android', 'ios'])).changed, false);
});
